#!/usr/bin/env python3
"""Vendor the ares SNES core and its support libraries at the pinned commit."""
import argparse
import json
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DEFAULT_PIN = ROOT / "tools" / "vendor" / "ares.json"
DEFAULT_DEST = ROOT / "external" / "ares"
COMMIT_RE = re.compile(r"\A[0-9a-f]{40}\Z")


def load_pin(path):
    try:
        pin = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise ValueError(f"cannot read pin {path}: {exc}") from exc
    if not isinstance(pin, dict):
        raise ValueError("pin must be a JSON object")
    repo, commit, paths = (pin.get("repo"), pin.get("commit"),
                           pin.get("paths"))
    if not isinstance(repo, str) or not repo or repo.startswith("-"):
        raise ValueError("pin repo must be a non-empty string not starting with '-'")
    if not isinstance(commit, str) or not COMMIT_RE.fullmatch(commit):
        raise ValueError("pin commit must be exactly 40 lowercase hex characters")
    if not isinstance(paths, list) or not paths:
        raise ValueError("pin paths must be a non-empty list")
    seen = set()
    for rel in paths:
        parts = rel.split("/") if isinstance(rel, str) else []
        if (not isinstance(rel, str) or not rel or rel.startswith("/")
                or any(part in ("", ".", "..", ".git") for part in parts)):
            raise ValueError(f"pin path is not a safe relative path: {rel!r}")
        if rel in seen:
            raise ValueError(f"duplicate pin path: {rel}")
        for other in seen:
            if rel.startswith(other + "/") or other.startswith(rel + "/"):
                raise ValueError(f"overlapping pin paths: {other} and {rel}")
        seen.add(rel)
    return repo, commit, paths


def resolve_destination(dest, protected, forbidden_trees=()):
    """Resolve dest, refusing locations whose deletion could destroy the repo,
    the user's home, the pin/script or a source checkout."""
    if dest.is_symlink():
        raise ValueError(f"refusing symlink destination: {dest}")
    resolved = dest.expanduser().resolve()
    if resolved == Path(resolved.anchor):
        raise ValueError(f"refusing filesystem root as destination: {resolved}")
    for p in protected:
        p = Path(p).expanduser().resolve()
        if resolved == p or resolved in p.parents:
            raise ValueError(
                f"refusing destination that contains protected path {p}: {resolved}")
    for p in forbidden_trees:
        p = Path(p).expanduser().resolve()
        if (resolved == p or p in resolved.parents
                or resolved in p.parents):
            raise ValueError(
                f"refusing destination overlapping source path {p}: {resolved}")
    return resolved


def check_source(root, paths):
    """Reject missing paths and every symlink before the destination is touched."""
    for rel in paths:
        top = root / rel
        if top.is_symlink():
            raise ValueError(f"symlink in pinned path: {rel}")
        if not top.exists():
            raise ValueError(f"pinned path missing at commit: {rel}")
        if top.is_dir():
            for p in top.rglob("*"):
                if p.is_symlink():
                    raise ValueError(
                        f"symlink in pinned path: {p.relative_to(root)}")


def copy_paths(source, dest, paths):
    for rel in paths:
        src = source / rel
        target = dest / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        if src.is_dir():
            shutil.copytree(src, target,
                            ignore=shutil.ignore_patterns(".git"))
        else:
            shutil.copy2(src, target)
    return sum(1 for p in dest.rglob("*") if p.is_file())


def write_manifest(dest, repo, commit, paths):
    (dest / "VENDORED.txt").write_text(
        f"repo: {repo}\n"
        f"commit: {commit}\n"
        f"paths: {' '.join(paths)}\n"
        "Generated by tools/vendor/vendor_ares.py. Do not edit files here; "
        "local changes go in patches/ares/.\n",
        encoding="utf-8")


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--pin", type=Path, default=DEFAULT_PIN)
    parser.add_argument("--dest", type=Path, default=DEFAULT_DEST)
    args = parser.parse_args(argv)
    try:
        repo, commit, paths = load_pin(args.pin)
        protected = [ROOT, args.pin, Path(__file__), Path.home()]
        dest = resolve_destination(args.dest, protected)
        if dest.exists() and not dest.is_dir():
            raise ValueError(f"destination is not a directory: {dest}")
        with tempfile.TemporaryDirectory() as tmp:
            source = Path(tmp)
            dest = resolve_destination(dest, protected,
                                       [source, ROOT / ".git"])
            subprocess.run(["git", "init", "-q"], cwd=tmp, check=True)
            subprocess.run(["git", "fetch", "-q", "--depth", "1", repo,
                            commit], cwd=tmp, check=True)
            subprocess.run(["git", "checkout", "-q", "FETCH_HEAD"], cwd=tmp,
                           check=True)
            check_source(source, paths)
            if dest.exists():
                shutil.rmtree(dest)
            dest.mkdir(parents=True)
            count = copy_paths(source, dest, paths)
            write_manifest(dest, repo, commit, paths)
    except (ValueError, OSError, subprocess.CalledProcessError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    print(f"vendored ares {commit} into {dest} ({count} files)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
